edits.before:
// Keep the drawer in the top layer until the exit transition ends, like
// Dialog does. close() removes the dialog from the top layer, which drops
// the native ::backdrop synchronously — the backdrop would disappear before
// it could transition out.
protected override _shouldDeferClose(): boolean {
  return this._isAnimated()
}

// Private

edits.after:
// Keep the drawer in the top layer until the exit transition ends, like
// Dialog does. close() removes the dialog from the top layer, which drops
// the native ::backdrop synchronously — the backdrop would disappear before
// it could transition out.
protected override _shouldDeferClose(): boolean {
  return this._isAnimated()
}

protected override async _show(relatedTarget?: HTMLElement): Promise<void> {
  await super._show(relatedTarget)
  // Move focus to the close button or first focusable element
  const focusable = this._element.querySelector('[data-bs-dismiss="drawer"]') as HTMLElement | null
  if (focusable) {
    focusable.focus({ preventScroll: true })
  } else {
    this._element.focus({ preventScroll: true })
  }
}

// Private

edits.before:
protected override _onBeforeShow(): void {
  this._initSwipe()
}

protected override _getInstantClassName(): string {
  return 'drawer-instant'
}

edits.after:
protected override _onBeforeShow(): void {
  this._initSwipe()
}

protected override async _show(relatedTarget?: HTMLElement): Promise<void> {
  await super._show(relatedTarget)
  // After the drawer is shown, move focus to the autofocus element if present,
  // otherwise to the close button, or the drawer itself as fallback.
  const autofocus = this._element.querySelector('[autofocus]') as HTMLElement | null
  if (autofocus) {
    autofocus.focus({ preventScroll: true })
  } else {
    const closeButton = this._element.querySelector('[data-bs-dismiss="drawer"]') as HTMLElement | null
    if (closeButton) {
      closeButton.focus({ preventScroll: true })
    } else {
      this._element.focus({ preventScroll: true })
    }
  }
}

protected override _getInstantClassName(): string {
  return 'drawer-instant'
}
